class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        # Split the string into runs of consecutive characters
        runs = []
        n = len(s)
        i = 0
        while i < n:
            current_char = s[i]
            count = 0
            while i < n and s[i] == current_char:
                count += 1
                i += 1
            runs.append(count)

        if not runs:
            return 0

        original_max = max(runs)
        low = 1
        high = original_max
        answer = original_max

        while low <= high:
            mid = (low + high) // 2
            total_flips = 0
            for L in runs:
                if mid >= L:
                    continue
                else:
                    numerator = L - mid
                    denominator = mid + 1
                    # Calculate ceil(numerator / denominator)
                    total_flips += (numerator + denominator - 1) // denominator
            if total_flips <= numOps:
                answer = mid
                high = mid - 1
            else:
                low = mid + 1
        return answer

